    // declare a node variable curr and
    // assign head node into curr node.
    Node *curr = head;

    // check that while curr->next is not equal
    // to NULL then curr points to next node.
    while (curr->next != nullptr)
        curr = curr->next;

    // assign curr->next to the head node.
    curr->next = head;

    return head;
